package dev.lumaphase.android.layout

/**
 * Mac reference presets, read unchanged from the bundled `layout.json` collection generated by
 * the Mac LayoutBuilder. They are source references at 1512×982, not this device's geometry.
 *
 * The asset carries all 16 combinations (four geometries × four pattern rotations); the UI only
 * offers four geometry labels plus the shared rotation choice. Geometry rectangles are never
 * rebuilt or adjusted here.
 */
data class MacReferenceSelection(
    val geometry: GeometryProfile,
    val rotationDeg: Int,
    val layout: ImportedLayout,
)

object MacReferenceLayouts {
    const val ASSET_PATH = "camera/macos-reference-layouts.json"
    const val REFERENCE_WIDTH_PX = 1512
    const val REFERENCE_HEIGHT_PX = 982
    const val SOURCE_REFERENCE = "$REFERENCE_WIDTH_PX×$REFERENCE_HEIGHT_PX"

    val GEOMETRIES: List<GeometryProfile> = listOf(
        GeometryProfile.F68_G6X12,
        GeometryProfile.C52_G5X12,
        GeometryProfile.F68,
        GeometryProfile.C52,
    )

    fun label(geometry: GeometryProfile): String = "Mac 参考 $SOURCE_REFERENCE · ${geometry.wire}"

    /** Parses and checks the bundled collection; a damaged asset is reported, never guessed. */
    fun load(text: String): List<ImportedLayout> {
        val layouts = LayoutJsonImport.parse(text)
        if (layouts.map { it.layoutId }.toSet().size != layouts.size) {
            throw LayoutImportException("Mac reference layout ids are not unique")
        }
        val expected = GEOMETRIES.flatMap { geometry ->
            BuiltInLayouts.ROTATIONS_DEG.map { rotation -> geometry.wire to rotation }
        }
        val present = layouts.mapNotNull { layout ->
            layout.geometry?.wire?.let { it to layout.patternRotationDeg }
        }.toSet()
        val missing = expected.filter { it !in present }
        if (missing.isNotEmpty()) {
            throw LayoutImportException("Mac reference layouts are incomplete: $missing")
        }
        if (layouts.any {
                it.drawableWidthPx != REFERENCE_WIDTH_PX ||
                    it.drawableHeightPx != REFERENCE_HEIGHT_PX
            }
        ) {
            throw LayoutImportException("Mac reference layouts are not $SOURCE_REFERENCE")
        }
        return layouts
    }

    /** Resolves one geometry/rotation pair from the parsed collection. */
    fun select(
        layouts: List<ImportedLayout>,
        geometryWire: String,
        rotationDeg: Int,
    ): MacReferenceSelection? {
        val geometry = GEOMETRIES.firstOrNull { it.wire == geometryWire } ?: return null
        if (rotationDeg !in BuiltInLayouts.ROTATIONS_DEG) return null
        val layout = layouts.firstOrNull {
            it.geometry?.wire == geometryWire && it.patternRotationDeg == rotationDeg
        } ?: return null
        return MacReferenceSelection(geometry, rotationDeg, layout)
    }
}
